def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return 0, 0

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def best_target(items, here, maximize=False):
        if not items:
            return None
        best = None
        best_score = None
        for item in items:
            p = pos(item)
            score = dist(here, p)
            if best is None or (maximize and score > best_score) or ((not maximize) and score < best_score):
                best = p
                best_score = score
        return best

    env = observation.get("environment_name", "") or ""
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    here = (sx, sy)
    opp = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") or "pursuer"
        if role == "pursuer":
            return step_toward(here, opp)
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_target(corners, opp, maximize=True) or (0, 0)
        return step_toward(here, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_target(targets, here, maximize=False)
        if target is not None:
            return step_toward(here, target)
        # fallback: move toward opponent / center-ish pressure
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        center = (w // 2 if w else sx, h // 2 if h else sy)
        if dist(here, opp) > dist(here, center):
            return step_toward(here, opp)
        return step_toward(here, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_target(resources, here, maximize=False)
    if target is not None:
        return step_toward(here, target)

    # Generic fallback: if no resources, pressure opponent but avoid standing still unless already aligned.
    if sx == ox and sy == oy:
        return [0, 0]
    return step_toward(here, opp)

